import json,re
ins=json.load(open('tr/p7-in-hi.json'))
M={}
M[ins[0]]="फ्लोरोमीथेन (HFC-{0}), {1}-डाइफ्लोरोएथेन (HFC-{2}) और {3}-डाइफ्लोरोएथेन (HFC-{4}a)"
M[ins[1]]="पेंटाफ्लोरोएथेन (HFC-{0}), {1}-ट्राइफ्लोरोएथेन (HFC-{2}a) और {3}-ट्राइफ्लोरोएथेन (HFC-{4})"
M[ins[2]]="{0}-टेट्राफ्लोरोएथेन (HFC-{1}a) और {2}-टेट्राफ्लोरोएथेन (HFC-{3})"
M[ins[3]]="{0}-हेप्टाफ्लोरोप्रोपेन (HFC-{1}ea), {2}-हेक्साफ्लोरोप्रोपेन (HFC-{3}cb), {4}-हेक्साफ्लोरोप्रोपेन (HFC-{5}ea) और {6}-हेक्साफ्लोरोप्रोपेन (HFC-{7}fa)"
M[ins[4]]="{0}-पेंटाफ्लोरोप्रोपेन (HFC-{1}fa) और {2}-पेंटाफ्लोरोप्रोपेन (HFC-{3}ca)"
M[ins[5]]="{0}-पेंटाफ्लोरोब्यूटेन (HFC-{1}mfc) और {2}-डेकाफ्लोरोपेंटेन (HFC-{3}-{4}mee)"
M[ins[6]]="{0}-टेट्राफ्लोरोप्रोपीन (HFO-{1}yf), {2}-टेट्राफ्लोरोप्रोपीन (HFO-{3}ze) और (z)-{4}-हेक्साफ्लोरो-{5}-ब्यूटीन (HFO-{6}mzz)"
M[ins[7]]="डोडेकेन-{0}-ऑल (लॉरिल अल्कोहल), हेक्साडेकेन-{1}-ऑल (सेटिल अल्कोहल) और ऑक्टाडेकेन-{2}-ऑल (स्टिअरिल अल्कोहल)"
M[ins[8]]="{0}, {1}, {2}-T(ISO) ({3}, {4}, {5}-ट्राइक्लोरोफेनॉक्सीएसिटिक अम्ल), उसके लवण और एस्टर"
M[ins[9]]="P-{0}-P मिथाइल ग्लाइसिडिक अम्ल और उसके"
M[ins[10]]="निःशुल्क भारत आयात शुल्क कैलकुलेटर: {0}+ HSN टैरिफ लाइनों को कोड या विवरण से खोजें, मूल देश चुनें और BCD, सोशल वेलफ़ेयर सरचार्ज, IGST, लैंडेड कॉस्ट तथा DGFT आयात नीति देखें."
M[ins[11]]="). मेल खाने वाली लाइन चुनें और शुल्क दर EU कॉमन कस्टम्स टैरिफ (TARIC) से अपने-आप भर जाएगी."
M[ins[12]]="शुल्क GCC के साझा बाहरी टैरिफ के अंतर्गत CIF मूल्य पर लगता है, जो ज़्यादातर {0}% है और जिसमें कई अपवाद हैं. दरें World Bank WITS के लागू टैरिफ, {1} के आँकड़ों से ली गई हैं, {2}-अंकीय HS स्तर पर. जहाँ एक HS कोड के भीतर राष्ट्रीय लाइनों की दरें अलग-अलग हों, वहाँ एक सीमा दिखाई जाती है और सबसे अधिक दर का उपयोग किया जाता है; पूरा {3}-अंकीय राष्ट्रीय कोड जाँच लें (GCC देश {5} में {4} अंकों पर चले गए). इसकी पुष्टि यहाँ करें:"
M[ins[13]]="). मेल खाने वाली लाइन चुनें और शुल्क दर World Bank WITS के लागू टैरिफ, {0} के आँकड़ों से अपने-आप भर जाएगी."
M[ins[14]]=". सऊदी अरब ने दिसंबर {0} में अपने टैरिफ में संशोधन किया, जो इस {1} के आँकड़ों में दिखाई नहीं दे सकता. CIF और शुल्क के योग पर {2}% VAT लगता है."
M[ins[15]]="दरें World Bank WITS के लागू टैरिफ, {0} के आँकड़ों से ली गई सामान्य आयात शुल्क (IGI) दरें हैं. आँकड़े पुरानी HS संख्या-प्रणाली पर आधारित हैं, इसलिए वर्तमान HS {1} के कुछ कोड अपने पुराने कोड के अंतर्गत दिखते हैं (उदाहरण के लिए, स्मार्टफ़ोन {2} के अंतर्गत). जहाँ एक HS कोड के भीतर टैरिफ लाइनों की दरें अलग-अलग हों, वहाँ एक सीमा दिखाई जाती है और सबसे अधिक दर का उपयोग किया जाता है. कस्टम्स प्रोसेसिंग शुल्क (DTA) सीमा शुल्क मूल्य के {3}% की दर से जोड़ा जाता है, और सीमा शुल्क मूल्य, IGI तथा DTA के योग पर {4}% IVA लगता है. मुक्त व्यापार समझौते वाले देशों (जैसे USMCA) से आने वाले माल पर कम दरें और एकमुश्त DTA लागू होते हैं; वे यहाँ लागू नहीं किए गए हैं. IEPS उत्पाद शुल्क और एंटी-डंपिंग शुल्क शामिल नहीं हैं. इसकी पुष्टि यहाँ करें:"
M[ins[16]]="अन्य अलेपित (अनकोटेड) कागज़ और पेपरबोर्ड, रोल या शीट में, आगे कार्य या प्रसंस्करण किए बिना…"
M[ins[17]]="सामग्रियों (जैसे धातु, लकड़ी, वस्त्र, कागज़, प्लास्टिक) की कठोरता, मज़बूती, संपीड्यता, प्रत्यास्थता या अन्य यांत्रिक गुणों के परीक्षण की मशीनें और उपकरण"
M[ins[18]]="सिविल विमान में उपयोग के लिए"
M[ins[19]]="श्वसन उपकरण (उनके भागों को छोड़कर), सिविल विमान में उपयोग के लिए"
M[ins[20]]="श्वसन उपकरण और गैस मास्क के भाग, कुछ प्रकार के विमानों में उपयोग के लिए"
M[ins[21]]="अपरिवर्तित प्रतिरक्षा-संबंधी (इम्यूनोलॉजिकल) उत्पाद, जो नोट में वर्णित प्राथमिक रूपों में पॉलीईथर हैं"
M[ins[22]]="अन्य अलेपित (अनकोटेड) कागज़ और पेपरबोर्ड, रोल या शीट में, इस अध्याय के नोट {0} में निर्दिष्ट से आगे कार्य या प्रसंस्कृत किए बिना › टेस्टलाइनर (रीसाइकल्ड लाइनर बोर्ड): {1}"
M[ins[23]]="). मेल खाने वाली लाइन चुनें और शुल्क दर ऑस्ट्रेलियन बॉर्डर फ़ोर्स टैरिफ से अपने-आप भर जाएगी."
for s in ins[24:]:
    m=re.match(r'^: ₹\{0\} per (\{1\} )?([A-Z]{3}) \(export rate ₹\{(\d)\}\)\. Exchange rate notification No\. \{(\d)\}/\{(\d)\}, in force from \{(\d)\}\.',s)
    assert m,s
    j=bool(m.group(1)); c=m.group(2); e,a,b,d=m.group(3),m.group(4),m.group(5),m.group(6)
    per=("{1} "+c) if j else c
    M[s]=f": प्रति {per} ₹{{0}} (निर्यात दर ₹{{{e}}}). विनिमय दर अधिसूचना सं. {{{a}}}/{{{b}}}, {{{d}}} से लागू. कस्टम्स बिल ऑफ एंट्री दाखिल करने की तिथि पर लागू दर का उपयोग करता है. आप इस दर को बदल सकते हैं."
assert len(M)==len(ins)
json.dump(M,open('tr/p7-out-hi.json','w'),ensure_ascii=False,indent=1)
